"""Generated bytes/fake kernel only; no file, process, model or network calls."""
import hashlib
import io
import json
import struct
import unittest

from reservation_file_port import RetainedJournal, PersistenceUnconfirmed
from snapshot_reservations import (MAGIC, ZERO, PhysicalSnapshot, SnapshotSemantics,
    GeneratedGateRegistry, ReservationService, ReservationRefused, decode_journal, encode_next)
from durable_lifecycle import DurableSnapshotLifecycle, DurableOwnedRuntimeFactory
from snapshot_lifecycle import Phase, SnapshotBusy

P = PhysicalSnapshot(7, "a" * 32)
S = SnapshotSemantics(7, "b" * 32, "choice", "revision", "c" * 64)
G = "d" * 64


class Worker:
    pass


class Fixture:
    def __init__(self, raw=b"", shared_gates=None):
        self.stream = io.BytesIO(raw)
        self.creation = object()
        self.finish = object()
        self.recovery = object()
        self.worker = Worker()
        self.events = []
        self.sync_action = None
        self.reconciliation_calls = []
        self.identity = (7, "e" * 32)
        self.journal = RetainedJournal(self.stream, lambda stream: self.identity, self.identity, self.sync)
        self.gates = shared_gates or GeneratedGateRegistry(
            lambda physical, evidence: physical == P and evidence is self.creation,
            self.confirm_recovery)
        self.service = ReservationService(self.gates, self.open, self.observe, self.confirm_finish)

    def open(self, physical):
        self.events.append("open")
        if physical != P:
            raise AssertionError("wrong physical file")
        return self.journal

    def sync(self, stream):
        self.events.append("sync")
        return self.sync_action() if self.sync_action else True

    def observe(self, worker):
        self.events.append("observe")
        if worker is not self.worker:
            raise ReservationRefused("foreign_worker")
        return [1234, 987654321000]

    def confirm_finish(self, worker, evidence):
        self.events.append("confirm_finish")
        return worker in (None, self.worker) and evidence is self.finish

    def confirm_recovery(self, physical, head, generation, evidence):
        self.reconciliation_calls.append((physical, head, generation, evidence))
        return physical == P and evidence is self.recovery

    def start(self, semantic=S, generation=G):
        creation = self.gates.register_generated_creation(P, self.creation)
        return self.service.begin(P, semantic, generation, creation)


def edited_last(raw, change):
    rows, _ = decode_journal(raw)
    row = rows[-1]
    change(row)
    payload = json.dumps(row, separators=(",", ":"), sort_keys=True).encode()
    length = struct.unpack_from("!I", raw, len(MAGIC))[0]
    assert len(rows) == 1
    return MAGIC + struct.pack("!I", len(payload)) + payload + hashlib.sha256(payload).digest()


class ReservationContracts(unittest.TestCase):
    def test_roundtrip_valid_history(self):
        raw = encode_next(b"", P, S, None, "INITIALIZED")
        raw += encode_next(raw, P, S, G, "RESERVED")
        raw += encode_next(raw, P, S, G, "WORKER_BOUND", process=[1234, 987654321000])
        rows, head = decode_journal(raw)
        self.assertEqual([row["phase"] for row in rows], ["INITIALIZED", "RESERVED", "WORKER_BOUND"])
        self.assertEqual(rows[-1]["process"], [1234, 987654321000])
        self.assertEqual(len(head), 64)

    def test_physical_gate_ignores_semantic_aliases(self):
        f = Fixture()
        token = f.start()
        alias = SnapshotSemantics(9, "f" * 32, "different-choice", "different-revision", "1" * 64)
        with self.assertRaisesRegex(ReservationRefused, "physical_snapshot_busy"):
            f.service.begin(P, alias, "2" * 64)
        self.assertIs(f.service._live[token.gate], token)

    def test_two_services_share_exact_gate(self):
        f = Fixture()
        f.start()
        second = Fixture(shared_gates=f.gates)
        with self.assertRaisesRegex(ReservationRefused, "physical_snapshot_busy"):
            second.service.begin(P, S, "2" * 64)
        self.assertEqual(second.events, [])

    def test_missing_initialization_does_not_create_state(self):
        f = Fixture()
        with self.assertRaisesRegex(ReservationRefused, "creation_evidence"):
            f.service.begin(P, S, G)
        self.assertEqual(f.stream.getvalue(), b"")
        self.assertIn(P, f.gates._held)

    def test_wrong_creation_evidence_refuses(self):
        f = Fixture()
        with self.assertRaisesRegex(ReservationRefused, "new_snapshot_not_observed"):
            f.gates.register_generated_creation(P, {"created": True})
        self.assertEqual(f.gates._new, {})

    def test_checksum_and_truncated_tail_refuse(self):
        raw = encode_next(b"", P, S, None, "INITIALIZED")
        with self.assertRaisesRegex(ReservationRefused, "checksum"):
            decode_journal(raw[:-1] + bytes([raw[-1] ^ 1]))
        with self.assertRaises(ReservationRefused):
            decode_journal(raw[:-1])
        with self.assertRaises(ReservationRefused):
            decode_journal(raw + b"x")

    def test_unknown_schema_and_sequence_refuse(self):
        raw = encode_next(b"", P, S, None, "INITIALIZED")
        with self.assertRaisesRegex(ReservationRefused, "schema"):
            decode_journal(edited_last(raw, lambda row: row.update(schema=2)))
        with self.assertRaises(ReservationRefused):
            decode_journal(edited_last(raw, lambda row: row.update(sequence=1)))

    def test_duplicate_fields_refuse(self):
        raw = encode_next(b"", P, S, None, "INITIALIZED")
        length = struct.unpack_from("!I", raw, len(MAGIC))[0]
        payload = raw[len(MAGIC) + 4:len(MAGIC) + 4 + length]
        payload = b'{"schema":1,' + payload[1:]
        forged = MAGIC + struct.pack("!I", len(payload)) + payload + hashlib.sha256(payload).digest()
        with self.assertRaisesRegex(ReservationRefused, "duplicate"):
            decode_journal(forged)

    def test_generation_reuse_and_bad_process_types_refuse(self):
        f = Fixture()
        token = f.start()
        with self.assertRaisesRegex(ReservationRefused, "process_observation"):
            encode_next(token.raw, P, S, G, "WORKER_BOUND", process=[True, 99])
        f.service.complete(token, f.finish)
        with self.assertRaisesRegex(ReservationRefused, "reservation_transition"):
            f.service.begin(P, S, G)

    def test_unrecognized_clean_restart_remains_blocked(self):
        f = Fixture()
        token = f.start()
        f.service.complete(token, f.finish)
        restarted = Fixture(f.stream.getvalue())
        with self.assertRaisesRegex(ReservationRefused, "restart_reconciliation_required"):
            restarted.service.begin(P, S, "2" * 64)
        self.assertIn(P, restarted.gates._held)

    def test_reserve_sync_failure_prevents_worker_binding(self):
        f = Fixture()
        creation = f.gates.register_generated_creation(P, f.creation)
        calls = []
        def fail_second():
            calls.append(1)
            return len(calls) != 2
        f.sync_action = fail_second
        with self.assertRaises(PersistenceUnconfirmed):
            f.service.begin(P, S, G, creation)
        self.assertNotIn("observe", f.events)
        self.assertIn(P, f.gates._held)
        self.assertEqual(decode_journal(f.stream.getvalue())[0][-1]["phase"], "RESERVED")

    def test_bind_sync_failure_retains_exact_worker_and_gate(self):
        f = Fixture()
        token = f.start()
        f.sync_action = lambda: False
        with self.assertRaises(PersistenceUnconfirmed):
            f.service.bind_worker(token, f.worker)
        self.assertIs(token.worker, f.worker)
        self.assertEqual(token.phase, "QUARANTINED")
        with self.assertRaises(ReservationRefused):
            f.service.require_resume(token)
        self.assertIn(P, f.gates._held)

    def test_foreign_worker_is_not_authorized_by_pid_data(self):
        f = Fixture()
        token = f.start()
        with self.assertRaisesRegex(ReservationRefused, "foreign_worker"):
            f.service.bind_worker(token, {"pid": 1234, "creation": 987654321000})
        self.assertEqual(decode_journal(f.stream.getvalue())[0][-1]["phase"], "RESERVED")

    def test_revoke_during_flush_refuses_late_resume(self):
        f = Fixture()
        token = f.start()
        observations = []
        def revoke():
            f.sync_action = None
            observations.append(f.service.quarantine(token, "operation_failed"))
            return True
        f.sync_action = revoke
        with self.assertRaisesRegex(ReservationRefused, "revoked_before_publication"):
            f.service.bind_worker(token, f.worker)
        self.assertEqual(observations, [False])
        self.assertTrue(token.revoked)
        self.assertTrue(f.service.quarantine(token, "operation_failed"))
        with self.assertRaises(ReservationRefused):
            f.service.resume_owned(token, lambda worker: self.fail("resume after revoke"))

    def test_resume_failure_is_one_attempt(self):
        f = Fixture()
        token = f.start()
        f.service.bind_worker(token, f.worker)
        calls = []
        def refuse(worker):
            calls.append(worker)
            return False
        with self.assertRaises(ReservationRefused):
            f.service.resume_owned(token, refuse)
        with self.assertRaises(ReservationRefused):
            f.service.resume_owned(token, refuse)
        self.assertEqual(calls, [f.worker])

    def test_forged_clear_evidence_cannot_drop_gate(self):
        f = Fixture()
        token = f.start()
        before = f.stream.getvalue()
        with self.assertRaisesRegex(ReservationRefused, "teardown_evidence"):
            f.service.complete(token, {"quiet": True})
        self.assertEqual(f.stream.getvalue(), before)
        self.assertIn(P, f.gates._held)

    def test_failed_clear_flush_keeps_local_and_restart_blocked(self):
        f = Fixture()
        token = f.start()
        f.sync_action = lambda: False
        with self.assertRaises(PersistenceUnconfirmed):
            f.service.complete(token, f.finish)
        self.assertEqual(decode_journal(f.stream.getvalue())[0][-1]["phase"], "CLEARED")
        self.assertEqual(token.phase, "QUARANTINED")
        self.assertIn(P, f.gates._held)
        restarted = Fixture(f.stream.getvalue())
        with self.assertRaisesRegex(ReservationRefused, "restart_reconciliation_required"):
            restarted.service.begin(P, S, "2" * 64)

    def test_current_reconciliation_binds_head_and_generation(self):
        original = Fixture()
        token = original.start()
        original.service.bind_worker(token, original.worker)
        raw = original.stream.getvalue()
        restarted = Fixture(raw)
        self.assertTrue(restarted.service.recover_existing(P, restarted.recovery))
        self.assertEqual(restarted.reconciliation_calls[0][:3], (P, decode_journal(raw)[1], G))
        self.assertEqual(decode_journal(restarted.stream.getvalue())[0][-1]["phase"], "CLEARED")
        self.assertNotIn(P, restarted.gates._held)
        self.assertEqual(restarted.service.begin(P, S, "2" * 64).phase, "RESERVED")

    def test_recovery_refuses_forged_evidence_and_corrupt_state(self):
        original = Fixture()
        original.start()
        raw = original.stream.getvalue()
        restarted = Fixture(raw)
        with self.assertRaisesRegex(ReservationRefused, "reconciliation_evidence"):
            restarted.service.recover_existing(P, {"pid_absent": True})
        self.assertEqual(restarted.stream.getvalue(), raw)
        corrupt = Fixture(raw[:-1])
        with self.assertRaises(ReservationRefused):
            corrupt.service.recover_existing(P, corrupt.recovery)
        self.assertEqual(corrupt.reconciliation_calls, [])

    def test_partial_writes_are_completed_and_identity_change_refuses(self):
        class Short(io.BytesIO):
            def write(self, raw):
                return super().write(raw[:3])
        stream = Short()
        identity = ["same"]
        journal = RetainedJournal(stream, lambda stream: identity[0], "same", lambda stream: True)
        self.assertEqual(journal.append_confirmed(b"", b"abcdefgh"), b"abcdefgh")
        identity[0] = "replacement"
        with self.assertRaisesRegex(PersistenceUnconfirmed, "identity"):
            journal.append_confirmed(b"abcdefgh", b"i")
        self.assertEqual(stream.getvalue(), b"abcdefgh")


class Kernel:
    def __init__(self, fixture):
        self.f = fixture
        self.protection = object()
        self.joined = self.released = False

    def acquire_read(self, key):
        self.f.events.append("acquire")
        return self.protection

    def create_suspended(self, protection, permit, profile):
        assert protection is self.protection
        self.f.events.append("create")
        return self.f.worker

    def resume(self, worker):
        assert worker is self.f.worker
        self.f.events.append("resume")
        return True

    def stop_start_failure(self, worker):
        assert worker is self.f.worker
        self.f.events.append("stop_exact")
        return True

    def quarantine(self, key, protection, permit, reason):
        self.f.events.append("kernel_quarantine")
        return False

    def close_and_join(self, worker, permit):
        assert worker is self.f.worker
        self.f.events.append("join")
        self.joined = True
        return True

    def confirm_quiescent(self, protection, worker, permit):
        self.f.events.append("quiet")
        return self.joined and worker is self.f.worker and protection is self.protection

    def release_read(self, protection):
        assert protection is self.protection
        self.f.events.append("release_guards")
        self.released = True
        return True

    def completion_evidence(self, worker):
        assert self.released and (worker is None or self.joined)
        return self.f.finish


class ConnectionContracts(unittest.TestCase):
    def setup(self):
        f = Fixture()
        creation = f.gates.register_generated_creation(P, f.creation)
        kernel = Kernel(f)
        manager = DurableSnapshotLifecycle(kernel, f.service, lambda *args: (P, S, G, creation))
        return f, kernel, manager

    def test_reservation_creation_binding_resume_and_clear_order(self):
        f, kernel, manager = self.setup()
        with manager.read_lease("generated", "choice", "revision") as lease:
            session = DurableOwnedRuntimeFactory(manager).open_owned_session(object(), lease.begin_native_session())
            self.assertEqual(f.events[:7], ["open", "sync", "sync", "acquire", "create", "observe", "sync"])
            self.assertEqual(f.events[7], "resume")
            self.assertTrue(session.close_and_join())
            lease.confirm_native_closed()
        self.assertLess(f.events.index("quiet"), f.events.index("release_guards"))
        self.assertLess(f.events.index("release_guards"), f.events.index("confirm_finish"))
        self.assertNotIn(P, f.gates._held)
        self.assertEqual(decode_journal(f.stream.getvalue())[0][-1]["phase"], "CLEARED")

    def test_binding_failure_stops_exact_worker_before_lease_exit(self):
        f, kernel, manager = self.setup()
        with self.assertRaises(PersistenceUnconfirmed):
            with manager.read_lease("generated", "choice", "revision") as lease:
                f.sync_action = lambda: False
                DurableOwnedRuntimeFactory(manager).open_owned_session(object(), lease.begin_native_session())
        self.assertIn("stop_exact", f.events)
        self.assertNotIn("resume", f.events)
        self.assertNotIn("release_guards", f.events)
        self.assertIn(P, f.gates._held)

    def test_lease_reuse_refuses_before_new_reservation(self):
        f, kernel, manager = self.setup()
        lease = manager.read_lease("generated", "choice", "revision")
        with lease:
            pass
        before = f.stream.getvalue()
        with self.assertRaises(SnapshotBusy):
            lease.__enter__()
        self.assertEqual(f.stream.getvalue(), before)


if __name__ == "__main__":
    unittest.main(verbosity=2)
